{"results": [{"id": "hp_doc_29f15e6d8eb18e95f30b7b88121fc6556e26af85d67f454e0dc199acdc78f610", "title": "Murray Walker", "text": "Graeme Murray Walker, {'1': \", '2': \", '3': \", '4': \"} (born 10 October 1923), known as Murray Walker, is an English semi-retired Formula One motorsport commentator and journalist. For most of his career he worked for the BBC, but when it lost the contract for Formula One coverage to ITV, he continued commentating after the change of broadcaster.", "score": 20.8797}, {"id": "hp_doc_011f5f49680b3c7d0ab64854ac4ec56f52f6c22d9b07da34d9c52659ad32f6bc", "title": "Grand Prix (TV programme)", "text": "Grand Prix was a British television programme based on the Formula One World Championship. It was primarily presented by the \"Voice of F1\" Murray Walker, who was also the lead commentator.", "score": 14.4015}, {"id": "hp_doc_830e3b15a4f456183fecbb34d8aaebe8d83ff82af92607099c5fec8f55006939", "title": "Matt Walker (ice hockey)", "text": "Matt Walker (born April 7, 1980) is a Canadian former professional ice hockey defenceman who played in the National Hockey League (NHL). During his nine NHL seasons he played for the St. Louis Blues, Chicago Blackhawks, Tampa Bay Lightning, and Philadelphia Flyers. He is the younger brother of former WHL player Darby Walker and cousin of former AHL goaltender Mike Walker.", "score": 11.1761}], "remaining_searches": 1}
